interface Shape { double area(); }
record Square(double side) implements Shape {
    public double area() { return side * side; }
}

void main() {
    Shape s = new Square(3);
    IO.println(s.area());
}

int depth(int n) {
    return n <= 1 ? 0 : 1 + depth(n / 2);
}

void main() {
    IO.println(depth(40));
}

